        const rowOffset = r * M;
        for (let c = 0; c < M; c++) {
            const u = rowOffset + c;
            const pU = P[u];

            if (c + 1 < M) {
                const v = u + 1;
                const pV = P[v];
                edgeU[edgeCount] = u;
                edgeV[edgeCount] = v;
                edgeW[edgeCount] = pU > pV ? pU : pV;
                edgeCount++;
