                const v = u + M;
                const pV = P[v];
                edgeU[edgeCount] = u;
                edgeV[edgeCount] = v;
                edgeW[edgeCount] = pU > pV ? pU : pV;
                edgeCount++;
            }
        }
    }

    const edgeIdx = new Int32Array(edgeCount);
    for (let i = 0; i < edgeCount; i++) {
        edgeIdx[i] = i;
    }
    edgeIdx.sort((a, b) => edgeW[a] - edgeW[b]);

    const totalNodes = 2 * V;
    const parentDsu = new Int32Array(totalNodes);
    for (let i = 0; i < totalNodes; i++) {
        parentDsu[i] = i;
    }

    function find(i) {
        let root = i;
        while (root !== parentDsu[root]) {
            root = parentDsu[root];
        }
        let curr = i;
        while (curr !== root) {
            let nxt = parentDsu[curr];
            parentDsu[curr] = root;
            curr = nxt;
        }
        return root;
    }

    const weight = new Int32Array(totalNodes);
    const sum = new Float64Array(totalNodes);
    const leftChild = new Int32Array(totalNodes);
    const rightChild = new Int32Array(totalNodes);

    for (let i = 0; i < V; i++) {
        sum[i] = P[i];
    }

    let currNode = V;
    for (let i = 0; i < edgeCount; i++) {
        const idx = edgeIdx[i];
        const ru = find(edgeU[idx]);
        const rv = find(edgeV[idx]);

        if (ru !== rv) {
            const p = currNode++;
            weight[p] = edgeW[idx];
            sum[p] = sum[ru] + sum[rv];
            leftChild[p] = ru;
            rightChild[p] = rv;
            parentDsu[ru] = p;
            parentDsu[rv] = p;
        }
    }

    const maxReachable = new Float64Array(totalNodes);
    const root = currNode - 1;
    maxReachable[root] = sum[root];

    for (let p = currNode - 1; p >= V; p--) {
        const L = leftChild[p];
        const R = rightChild[p];
        const W = weight[p];

        maxReachable[L] = (sum[L] >= W) ? maxReachable[p] : sum[L];
        maxReachable[R] = (sum[R] >= W) ? maxReachable[p] : sum[R];
    }

    let out = '';
    for (let r = 0; r < N; r++) {
        const rowOffset = r * M;
        const row = [];
        for (let c = 0; c < M; c++) {
            row.push(maxReachable[rowOffset + c]);
        }
        out += row.join(' ') + '\n';
        if (out.length > 65536) {
            process.stdout.write(out);
            out = '';
        }
    }
    if (out.length > 0) {
        process.stdout.write(out);
    }
}

